    solver.add(Sum([If(edges[i][j], 1, 0) for i in range(n) for j in range(i+1, n)]) >= E)

    # Girth >= 6 means no C3, C4, C5
    # No C3
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                solver.add(Or(Not(edges[i][j]), Not(edges[j][k]), Not(edges[i][k])))

    # No C4
    for i in range(n):
