                    # i-j-k-l-i
                    solver.add(Or(Not(edges[i][j]), Not(edges[j][k]), Not(edges[k][l]), Not(edges[i][l])))
                    # i-j-l-k-i
                    solver.add(Or(Not(edges[i][j]), Not(edges[j][l]), Not(edges[l][k]), Not(edges[i][k])))
