                    solver.add(Or(Not(edges[i][k]), Not(edges[k][j]), Not(edges[j][l]), Not(edges[i][l])))

    # No C5
    import itertools
    for p in itertools.permutations(range(n), 5):
        if p[0] < p[1] and p[0] < p[4] and p[1] < p[4]:
            solver.add(Or(
                Not(edges[min(p[0], p[1])][max(p[0], p[1])]),
