from pysat.solvers import Glucose3
from pysat.formula import WCNF
from itertools import combinations

n = 14
solver = Glucose3()

def var(i, j):
    if i > j:
        i, j = j, i
    return i * n + j + 1

# No C3
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            solver.add_clause([-var(i,j), -var(j,k), -var(i,k)])

# No C4
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                solver.add_clause([-var(i,j), -var(j,k), -var(k,l), -var(i,l)])
                solver.add_clause([-var(i,j), -var(j,l), -var(l,k), -var(i,k)])
                solver.add_clause([-var(i,k), -var(k,j), -var(j,l), -var(i,l)])

# No C5
import itertools
for p in itertools.permutations(range(n), 5):
    if p[0] < p[1] and p[0] < p[4] and p[1] < p[4]:
        solver.add_clause([
            -var(p[0], p[1]),
            -var(p[1], p[2]),
            -var(p[2], p[3]),
            -var(p[3], p[4]),
            -var(p[4], p[0])
        ])

# At least 26 edges
from pysat.card import CardEnc
edges = [var(i, j) for i in range(n) for j in range(i+1, n)]
cnf = CardEnc.atleast(lits=edges, bound=26, encoding=1)
for clause in cnf.clauses:
    solver.add_clause(clause)

print(solver.solve())
